sys_script.script:
/* global sn_hr_core */
(
    function executeRule(current) { //..., previous /*null when async*/ (ESLint didn't like it)
        gs.debug("Case: " + current.number +
            "\n1.OHSM info: " +
            "\n\tBusiness rule: " +
            "\n\t\t'HoC - Multiple workflows - Generate PDF based on pdf_template field'" +
            "\nstarts here---------------------------------------------------------"
        );
        current.auto_create_draft_document = true; //from table sn_hr_core_case
        if (current.auto_create_draft_document) {
            gs.debug("2.OHSM info: is PDF Template field value null? " +
                gs.nil(current.pdf_template) + " " + current.number);

            if (new sn_hr_core.hr_PdfUtils().isValidPdfTemplateForPreFill(current.pdf_template.sys_id)) {
                gs.debug("3.OHSM info: isValidPdfTemplateForPreFill is true " + current.number);

                var pdfDraftSysId = new sn_hr_core.hr_PdfUtils().prefillPdfTemplate(
                    current.pdf_template.sys_id, false, current.sys_id, current.sys_class_name, current.sys_id
                );

                if (gs.nil(pdfDraftSysId)) {
                    gs.warn("OHSM info:\nCase: " + current.number + "4.pdfDraftSysId is null. " +
                        "Error occurred while generating pdf");
                } else {
                    gs.addInfoMessage(gs.getMessage("x_hccc_hoc_ohs.document_has_been_created"));
                }

            } else {
                gs.debug("5.OHSM info: isValidPdfTemplateForPreFill is false " + current.number);
                if (current.pdf_template.changes()) {
                    new sn_hr_core.GeneralHRForm().inactivateRelatedDrafts(current.sys_class_name, current.sys_id);
                }

                gs.debug("6.OHSM info: caseAjax call for " + current.number);
                try {
                    var caseAjax = new sn_hr_core.hr_CaseAjax();
                    var document = caseAjax.documentBody(
                        current.sys_class_name, current.sys_id, current.sys_class_name, current.sys_id, 'true'
                    );

                    caseAjax.setDocumentBody(
                        document.body, current.sys_class_name, current.sys_id, current.sys_class_name, current.sys_id
                    );
                } catch (e) {
                    var errorString = JSON.stringify(e, Object.getOwnPropertyNames(e), '\t')
                        .replaceAll('\\t', 't')
                        .replaceAll('\\n', '\n');

                    gs.error("OHSM info:\nCase: " + current.number + "\n\nerror:\n" +
                        errorString);
                }

            }
        }
        gs.debug("Case: " + current.number +
            "\n7.OHSM info: " +
            "\n\tBusiness rule: " +
            "\n\t\t'HoC - Multiple workflows - Generate PDF based on pdf_template field'" +
            "\nends here---------------------------------------------------------"
        );
    }

)(current, previous);
